import os, json
def transform(grid):
    h=len(grid); w=len(grid[0])
    out=[row[:] for row in grid]
    # find the line row (row with non-zero cells)
    for r in range(h):
        if any(v!=0 for v in grid[r]):
            lr=r; break
    heights={2:3, 8:2}
    for c in range(w):
        v=grid[lr][c]
        if v!=1:
            n=heights[v]
            for k in range(1,n+1):
                out[lr-k][c]=1
            out[lr-n-1][c]=v
    return out

